"""Keep box inflation arithmetic scalar under Mono AOT."""

def optimize_scalar_bounds(out, replace, override):
    override('Spatial/BoundingBox.cs', [('public readonly BoundingBox Inflate(float amount)\n\t{', 'public readonly BoundingBox Inflate(float amount)\n    {\n        if(!float.IsFinite(amount) || !float.IsFinite(Min.X) || !float.IsFinite(Min.Y) || !float.IsFinite(Min.Z)\n            || !float.IsFinite(Max.X) || !float.IsFinite(Max.Y) || !float.IsFinite(Max.Z)) return InflateReference(amount);\n        float padding=(1f*amount)*2f;\n        float sx=((Max.X-Min.X)+padding)/2f;\n        float sy=((Max.Y-Min.Y)+padding)/2f;\n        float sz=((Max.Z-Min.Z)+padding)/2f;\n        float cx=(Min.X+Max.X)/2f;\n        float cy=(Min.Y+Max.Y)/2f;\n        float cz=(Min.Z+Max.Z)/2f;\n        var result=new BoundingBox(new Vec3(cx-sx,cy-sy,cz-sz),new Vec3(cx+sx,cy+sy,cz+sz));\n        if(!float.IsFinite(result.Min.X) || !float.IsFinite(result.Min.Y) || !float.IsFinite(result.Min.Z)\n            || !float.IsFinite(result.Max.X) || !float.IsFinite(result.Max.Y) || !float.IsFinite(result.Max.Z)) return InflateReference(amount);\n        return result;\n    }\n    private readonly BoundingBox InflateReference(float amount)\n    {')])
